(function(){"use strict";document.addEventListener("click",function(e){var l=e.target.closest?e.target.closest(".sc-scroll-cue"):null;if(l){var t=l.getAttribute("href")||"";if(t.charAt(0)==="#"&&t.length>1){var r=null;try{r=document.querySelector(t)}catch{r=null}r&&(e.preventDefault(),r.scrollIntoView({behavior:"smooth",block:"start"}));return}(l.hasAttribute("data-scroll-down")||t==="#"||t==="")&&(e.preventDefault(),window.scrollBy({top:Math.round(window.innerHeight*.9),left:0,behavior:"smooth"}))}},!1)})();
